# Validate a list of prescriptions
prescriptions = [
    {"drug": "Amoxicillin", "dose_mg": 500, "max": 2000},
    {"drug": "Ibuprofen",  "dose_mg": 800, "max": 1200},
    {"drug": "Methotrexate", "dose_mg": 25, "max": 20},
]

for rx in prescriptions:
    if rx["dose_mg"] > rx["max"]:
        print(f"REJECT {rx['drug']}: exceeds max {rx['max']}mg")
    elif rx["dose_mg"] > 0.8 * rx["max"]:
        print(f"REVIEW {rx['drug']}: dose near maximum")
    else:
        print(f"APPROVE {rx['drug']} at {rx['dose_mg']}mg")
